const vidInput = String(tobub.params.vid || '').trim();
const probabilityPercent = Number(tobub.params.probability ?? 20);
const maxLikes = Number(tobub.params.maxLikes ?? 3);
const commentContains = String(tobub.params.commentContains ?? '').trim().toLocaleLowerCase();
const minCommentLength = Number(tobub.params.minCommentLength ?? 0);
const maxPages = Number(tobub.params.maxPages ?? 6);
const dryRun = tobub.params.dryRun === true;
if (!vidInput || vidInput.length > 2048) throw new Error('Enter a TikTok video ID or URL.');
if (!Number.isFinite(probabilityPercent) || probabilityPercent < 0 || probabilityPercent > 100) throw new Error('probability must be a number from 0 to 100.');
if (!Number.isInteger(maxLikes) || maxLikes < 1 || maxLikes > 10) throw new Error('maxLikes must be an integer from 1 to 10.');
if (commentContains.length > 100) throw new Error('commentContains must be at most 100 characters.');
if (!Number.isInteger(minCommentLength) || minCommentLength < 0 || minCommentLength > 500) throw new Error('minCommentLength must be an integer from 0 to 500.');
if (!Number.isInteger(maxPages) || maxPages < 1 || maxPages > 20) throw new Error('maxPages must be an integer from 1 to 20.');
const allowedHosts = new Set(['tiktok.com', 'www.tiktok.com', 'm.tiktok.com']);
let videoId = vidInput;
let videoUrl;
if (/^\d{8,24}$/.test(vidInput)) videoUrl = 'https://www.tiktok.com/video/' + vidInput;
else {
  let parsed;
  try { parsed = new URL(/^[a-z][a-z0-9+.-]*:\/\//i.test(vidInput) ? vidInput : 'https://' + vidInput); }
  catch { throw new Error('Invalid TikTok video URL.'); }
  if (!allowedHosts.has(parsed.hostname.toLowerCase()) || !['http:', 'https:'].includes(parsed.protocol)) throw new Error('Use an official TikTok video URL or video ID.');
  const match = parsed.pathname.match(/\/video\/(\d{8,24})(?:\/|$)/);
  if (!match) throw new Error('The video URL must contain a numeric video ID after /video/.');
  videoId = match[1];
  videoUrl = 'https://www.tiktok.com' + parsed.pathname;
}
const likeSelector = '[data-key-interaction="comment_like"]';
const probability = probabilityPercent / 100;
const records = [];
let checkedCount = 0;
let filteredCount = 0;
let likedCount = 0;
let verifiedCount = 0;
let wouldLikeCount = 0;
await tobub.atoms.navigate({ url: videoUrl, waitUntil: 'domcontentloaded' });
await tobub.atoms.waitFor({ selector: 'button[data-testid="tux-web-tab-bar"]', selectorState: 'attached' }, { timeout: 20000 });
await tobub.atoms.waitFor({ delay: 4000 });
try { await tobub.atoms.click({ selector: 'button[data-testid="tux-web-tab-bar"]', nth: 0, visibleOnly: true }); } catch {}
await tobub.atoms.waitFor({ delay: 1800 });
for (let page = 0; page < maxPages && (dryRun ? wouldLikeCount : likedCount) < maxLikes; page++) {
  const result = await tobub.atoms.evaluate({
    mode: 'expression',
    expression: '(()=>{const all=Array.from(document.querySelectorAll("[data-key-interaction=\\"comment_like\\"]"));const vw=innerWidth,vh=innerHeight;return all.map((control,index)=>{const r=control.getBoundingClientRect();let root=control;for(let depth=0;depth<8&&root;depth++,root=root.parentElement){if(root.querySelector("[data-e2e=\\"comment-level-1\\"]"))break}const comment=root&&root.querySelector("[data-e2e=\\"comment-level-1\\"]");const username=root&&root.querySelector("[data-e2e^=\\"comment-username-\\"]");const aria=control.getAttribute("aria-label")||"";return{controlIndex:index,visible:r.width>0&&r.height>0&&r.bottom>0&&r.top<vh&&r.right>0&&r.left<vw&&getComputedStyle(control).visibility!=="hidden",text:comment?(comment.innerText||"").trim().slice(0,280):"",username:username?(username.innerText||"").trim().slice(0,100):"",likeLabel:aria,unliked:control.getAttribute("aria-pressed")!=="true"&&/^Like video/i.test(aria)}}).filter(x=>x.visible&&x.likeLabel)})()'
  });
  const items = result && result.value !== undefined ? result.value : (result && result.result !== undefined ? result.result : result);
  if (Array.isArray(items)) {
    const filteredItems = items.filter(item => {
      const normalizedText = String(item.text || '').toLocaleLowerCase();
      const length = Array.from(String(item.text || '')).length;
      const keep = length >= minCommentLength && (!commentContains || normalizedText.includes(commentContains));
      if (!keep) filteredCount++;
      return keep;
    });
    for (let itemIndex = filteredItems.length - 1; itemIndex >= 0; itemIndex--) {
      const item = filteredItems[itemIndex];
      if ((dryRun ? wouldLikeCount : likedCount) >= maxLikes) break;
      checkedCount++;
      const decision = tobub.utils.chance(probability);
      const record = { sequence: checkedCount, commentIndex: item.controlIndex, comment: item.text, before: item.likeLabel, decision: decision ? 'like' : 'skip', clicked: false, verified: false };
      records.push(record);
      if (!item.unliked || !decision) continue;
      if (dryRun) {
        record.decision = 'preview';
        wouldLikeCount++;
        continue;
      }
      try {
        await tobub.atoms.click({ selector: likeSelector, nth: item.controlIndex, visibleOnly: true });
        record.clicked = true;
        likedCount++;
        await tobub.atoms.waitFor({ delay: 450 });
        const verify = await tobub.atoms.evaluate({
          mode: 'expression',
          expression: '(()=>{const e=document.querySelectorAll("[data-key-interaction=\\"comment_like\\"]")[INDEX];return!!e&&(e.getAttribute("aria-pressed")==="true"||/^Unlike video/i.test(e.getAttribute("aria-label")||""))})()'.replace('INDEX', String(item.controlIndex))
        });
        const value = verify && verify.value !== undefined ? verify.value : verify;
        record.verified = value === true;
        if (record.verified) verifiedCount++;
      } catch (error) {
        record.error = String(error).slice(0, 180);
      }
    }
  }
  if ((dryRun ? wouldLikeCount : likedCount) >= maxLikes) break;
  const scroll = await tobub.atoms.evaluate({
    mode: 'expression',
    expression: '(()=>{const marker=document.querySelector("[data-e2e=\\"comment-level-1\\"]");let el=marker;for(let i=0;i<8&&el;i++,el=el.parentElement){const s=getComputedStyle(el);if(el.scrollHeight>el.clientHeight+40&&/(auto|scroll)/.test(s.overflowY)){const before=el.scrollTop;el.scrollTop=Math.min(el.scrollHeight,el.scrollTop+Math.max(300,el.clientHeight*.8));return{found:true,before,after:el.scrollTop}}}return{found:false}})()'
  });
  const state = scroll && scroll.value !== undefined ? scroll.value : scroll;
  if (!state || !state.found || (state.after <= state.before && state.before > 0)) break;
  await tobub.atoms.waitFor({ delay: 900 });
}
return {
  videoId,
  videoUrl,
  probabilityPercent,
  dryRun,
  commentContains,
  minCommentLength,
  maxPages,
  checkedCount,
  filteredCount,
  wouldLikeCount,
  likedCount,
  verifiedCount,
  complete: verifiedCount === likedCount,
  warning: dryRun ? (wouldLikeCount ? 'Preview mode: matching comments are listed, and no likes were performed.' : 'Preview mode: no comments matched the filters or probability sampling selected none.') : (likedCount === 0 ? 'No likes were attempted. There may be no matching unliked comments, or probability sampling may have skipped them.' : (verifiedCount === likedCount ? '' : 'Like clicks were sent, but the page could not confirm every like state change.')),
  records
};
